    }

    await walk(dir);
    files.sort((a, b) => a.$1.compareTo(b.$1));
    final buffer = StringBuffer('$dir/$entryFile\n');
    for (final (path, text) in files) {
      buffer.write('$path\n$text\n');
    }
    return sha256.convert(utf8.encode(buffer.toString())).toString();
