  static FaLlmMessage _parseLlmMessage(Object? entry) {
    if (entry is! Map) {
      throw StateError('each message must be a {role, content} object');
    }
    final role = (entry['role'] ?? '').toString();
    const roles = {'user', 'assistant', 'system'};
    if (!roles.contains(role)) {
