Future<AgentService> createAppBoundSession(
  FlutterSessionManager manager,
  String appId,
) async {
  final active = manager.active!.service;
  final config =
      active.configForClone ??
      AgentConfig(
        providerKind: active.providerKind,
        modelId: active.modelId,
        baseUrl: '',
        apiKey: '',
