  /// sessions with it), or the fs root. Session-affecting mutations
  /// persist eagerly (skip the debounce).
  static bool _affectsSessions(String path) =>
      _isSessionPath(path) ||
      path == '/' ||
      path.isEmpty ||
      path == '/sessions';

