  @override
  void dispose() {
    widget.fsRevision?.removeListener(_onFsRevision);
    _agentService?.removeListener(_onAgentServiceEvent);
    _reloadDebounce?.cancel();
    unawaited(_engine?.dispose() ?? Future.value());
