  static String _resolvePath(String baseDir, String relPath) {
    final segments = '$baseDir/$relPath'.split('/');
    final out = <String>[];
    for (final segment in segments) {
      if (segment == '.' || segment.isEmpty) continue;
      if (segment == '..') {
        if (out.isNotEmpty) out.removeLast();
