      final content = await reader.readString(absPath);
      if (content != null) {
        final stripped = content.replaceAll(_exportRegex, '');
        buffer.write(
          await _preprocessIncludes(
            stripped,
            _parentOf(absPath),
            depth + 1,
            reader,
            visited,
          ),
        );
