      'apps/../evil', // namespace escape through the root
      'a_b', // underscore
      'My-App', // uppercase
      'приложение', // unicode
      'a b', // space
      'a.b', // dot
      '.hidden', // dot-file
      '-abc', // leading dash
      'a/b', // separator
      'a\\b', // windows separator
      'a${'x' * 32}', // 33 chars — over the bound
    ];
