      expect(AppStorage.manifestPath('2048'), 'apps/2048/manifest.json');
      expect(AppStorage.entryPath('2048'), 'apps/2048/widget.js');
      expect(
        AppStorage.entryPath('2048', 'widget_tile.js'),
        'apps/2048/widget_tile.js',
      );
    });

