/// The honest gh-1614 boot failure: names the storage root and the exact
/// missing paths (I3) — never a bare "not found".
static Future<String> _bootFailure(ExecutionEnv env, String dir, String entryFile) async {
  final missing = <String>[
    if ((await env.exists(AppStorage.manifestPath(...))).valueOrNull != true)
      '$dir/${AppStorage.manifestFile}',
    if ((await env.exists('$dir/$entryFile')).valueOrNull != true)
      '$dir/$entryFile',
