/// The single app-storage namespace: every `apps/<id>/` path the Apps tab
/// lists, reads, writes, or boots resolves through [appDir]/[appFile] here —
/// one validator, one clamp, no second path normalization (gh-1614 I1).
class AppStorage {
  /// Valid app id: `^[a-z0-9][a-z0-9-]{1,31}$`.
  static final RegExp idPattern = RegExp(r'^[a-z0-9][a-z0-9-]{1,31}$');
  static const String root = 'apps';
  static bool isValidId(String id) => idPattern.hasMatch(id);
  /// Resolves `apps/<id>` or throws ArgumentFormatException naming the id.
