      '', // empty
      'a', // single char is fine — covered above; the rest reject:
      '..', // traversal
      '../x', // traversal
      'a/../b', // embedded traversal
      'a/..', // trailing traversal
      '/absolute', // absolute
      'apps/../evil', // namespace escape through the root
