```dart
// Copyright ...

import 'package:fa/apps_store.dart'; // NO — circular. AppStorage is standalone.

/// The single app-storage namespace (gh-1614 I1).
///
/// Every `apps/<id>/…` path — the Apps tab's listing, the engine's boot
/// reads, install writes — resolves through [appDir]/[appFile] here: one
/// validator, one clamp, no second path normalization. Listing and reading
/// therefore cannot diverge (the gh-1614 "listed but unreadable" defect),
/// and an id or path arriving from user storage can never escape the
/// namespace (gh-1614 AC4).
final class AppStorage {
  AppStorage._();

  /// Namespace root every app directory lives under.
  static const String root = 'apps';

  /// The boot entry every manifest namespace names.
  static const String defaultEntry = 'widget.js';

  /// The manifest every app carries.
  static const String manifestFile = 'manifest.json';

  /// App-id rule (gh-1614): 2–32 chars of lowercase alnum + dashes,
  /// starting with alnum. Rejects traversal (`..`), separators, absolute
  /// paths, dot-files, uppercase and unicode look-alikes — an id outside
  /// the pattern cannot name a path that escapes `<root>/<id>/`.
  static final RegExp idPattern = RegExp(r'^[a-z0-9][a-z0-9-]{1,31}$');

  static bool isValidId(String id) => idPattern.hasMatch(id);

  /// A single safe path segment inside an app dir ...
  static final RegExp _segmentPattern = RegExp(r'^[A-Za-z0-9._-]{1,128}$');

  static bool isValidSegment(String segment) =>
      segment != '.' && segment != '..' && _segmentPattern.hasMatch(segment);

  /// Resolves `apps/<id>` — throws [ArgumentError] when [id] cannot live
  /// in the namespace (gh-1614 AC4: rejected at read).
  static String appDir(String id) {
    if (!isValidId(id)) {
      throw ArgumentError.value(id, 'id',
          'app id must match ${idPattern.pattern} (got "$id") — the path '
          'would leave the $root/ namespace');
    }
    return '$root/$id';
  }

  /// Null-returning [appDir] for listing ...
  static String? tryAppDir(String id) => isValidId(id) ? '$root/$id' : null;

  /// Resolves a file under the app dir. [relative] may carry subdirectories
  /// (`game/main.js`) — every segment is validated, so the result always
  /// stays under `apps/<id>/`.
  static String appFile(String id, String relative) {
    final segments = relative.split('/');
    for (final s in segments) {
      if (!isValidSegment(s)) throw ArgumentError.value(relative, 'relative', ...);
    }
    return '${appDir(id)}/$relative';
  }

  static String manifestPath(String id) => appFile(id, manifestFile);
  static String entryPath(String id, [String entry = defaultEntry]) => appFile(id, entry);
}
```

