/// Lexically normalizes [path] and requires it to stay under [dir].
String? _normalizeUnderDir(String path) {
  final segments = path.replaceAll('\\', '/').split('/');
  final out = <String>[];
  for (final segment in segments) {
    if (segment.isEmpty || segment == '.') continue;
    if (segment == '..') { if (out.isEmpty) return null; out.removeLast(); continue; }
    out.add(segment);
