  static bool isValidRelativePath(String relative) {
    if (relative.isEmpty) return false;
    for (final segment in relative.split('/')) {
      if (segment == '.' || segment == '..') return false;
      if (!_segmentPattern.hasMatch(segment)) return false;
    }
