  static bool isSafeDir(String dir) {
    if (dir.isEmpty) return false;
    for (final segment in dir.split('/')) {
      if (segment == '.' || segment == '..') return false;
      if (!_segmentPattern.hasMatch(segment)) return false;
    }
    return true;
