  static String appDir(String id) {
    if (!isResolvableId(id)) {
      throw ArgumentError(
        'app id "$id" cannot be resolved under $root/ — an id must be a '
        'single plain segment (no "..", no "/", no absolute form; the '
        'path would leave the $root/ namespace)',
      );
