    if (!isValidRelativePath(relative)) {
      throw ArgumentError(
        'path "$relative" cannot be resolved under $root/$id/ — every '
        'segment must match ${_segmentPattern.pattern} and no segment may '
        'be "." or ".."',
      );
    }
